(6998084, 1056674, 83149, '<td valign="top">I like the processing but not the cropping across the chest.  I think it would have worked better to have only the legs in the frame.</td>', 'I like the processing but not the cropping across the chest.  I think it would have worked better to have only the legs in the frame.', '2013-03-12 19:47:56.000000', NULL, 1),
(6998086, 1056789, 83149, '<td valign="top">Nicely done.  Love the facial expression.  One small point is that the line in the background is slightly distracting.  Still one of my favourites from the challenge though.</td>', 'Nicely done.  Love the facial expression.  One small point is that the line in the background is slightly distracting.  Still one of my favourites from the challenge though.', '2013-03-12 19:49:46.000000', NULL, 1),
(6998089, 1056692, 83149, '<td valign="top">The cropping at the chin just doesn''t work for me.  I like the processing but I think it would have been better with her face in frame.</td>', 'The cropping at the chin just doesn''t work for me.  I like the processing but I think it would have been better with her face in frame.', '2013-03-12 19:52:08.000000', NULL, 1),
