(6998103, 1056228, 30982, '<td valign="top">Nice use of long exposure.  Would not have guessed the "B" without your title.  I would have guessed A for Arch, perhaps.  Or S for Sea of Green.  Peaceful shot.</td>', 'Nice use of long exposure.  Would not have guessed the "B" without your title.  I would have guessed A for Arch, perhaps.  Or S for Sea of Green.  Peaceful shot.', '2013-03-12 20:08:01.000000', NULL, 1),
