(6998679, 1056657, 153814, '<td valign="top">Paul this was my pick for the blue ribbon.<br/>Seagulls are arguably the most photographed bird in the world and we have seen <br/>thousands upon thousands of seagull shots to compare this too.<br/>BUT to have this kind of action and reaction in a seagull shot(or any wildlife shot)for that matter is just superb.<br/>You have taken the ordinary and made it extraordinary.<br/>On top of that I see 3 B''s in your shot Birds, Beach, Bite. What more could you ask for.<br/>This is truely a shot to be proud of.<br/> <br/>On a side note Hahn23 said these are ring-billed gulls but judging by their size and the tip of their beaks being black my guess would be Herring gull.<br/>It''s a bit hard to tell from the picture but that would be my guess.<br/>Again congrats on a great shot.</td>', 'Paul this was my pick for the blue ribbon.Seagulls are arguably the most photographed bird in the world and we have seen thousands upon thousands of seagull shots to compare this too.BUT to have this kind of action and reaction in a seagull shot(or any wildlife shot)for that matter is just superb.You have taken the ordinary and made it extraordinary.On top of that I see 3 B''s in your shot Birds, Beach, Bite. What more could you ask for.This is truely a shot to be proud of. On a side note Hahn23 said these are ring-billed gulls but judging by their size and the tip of their beaks being black my guess would be Herring gull.It''s a bit hard to tell from the picture but that would be my guess.Again congrats on a great shot.', '2013-03-13 07:35:26.000000', NULL, 0),
(6998681, 1056779, 76335, '<td valign="top">Bela Fleck and Benji. Reminds me of a busker in our Strip District here. He brings his dog too, but his dog is <i>stuffed</i>. <br/> <br/>I like the framing. More would be less.</td>', 'Bela Fleck and Benji. Reminds me of a busker in our Strip District here. He brings his dog too, but his dog is stuffed.  I like the framing. More would be less.', '2013-03-13 07:37:04.000000', NULL, 0),
(6998682, 1056529, 76335, '<td valign="top">I like the up close, tight framing. A bit chaotic in black and white, but fun to decipher.</td>', 'I like the up close, tight framing. A bit chaotic in black and white, but fun to decipher.', '2013-03-13 07:38:22.000000', NULL, 0),
(6998684, 1056103, 76335, '<td valign="top">I rather like your messy background.<br/><br/><i>Message edited by author 2013-03-13 07:39:20.</i></td>', 'I rather like your messy background.', '2013-03-13 07:39:09.000000', '2013-03-13 07:39:20.000000', 0),
