(6999354, 1056192, 65319, '<td valign="top">I can''t wait to show this to my daughter.  She''s has those exact same bunny ears!  Now she''s gonna want your dog too...LOL!</td>', 'I can''t wait to show this to my daughter.  She''s has those exact same bunny ears!  Now she''s gonna want your dog too...LOL!', '2013-03-13 18:24:38.000000', NULL, 0),
(6999551, 1056622, 138630, '<td valign="top">An excellent portrait which I gave a top score.  I didn''t any DNMC for shoehorns in this challenge - would have been too hard to determine.  So I gave the benefit of the doubt to every entry on suitability for challenge and just looked at the photos as free studies - loved this.</td>', 'An excellent portrait which I gave a top score.  I didn''t any DNMC for shoehorns in this challenge - would have been too hard to determine.  So I gave the benefit of the doubt to every entry on suitability for challenge and just looked at the photos as free studies - loved this.', '2013-03-14 00:30:32.000000', NULL, 0),
(7000062, 1056228, 66952, '<td valign="top">I see you''re putting your travel to good use. Congrats!</td>', 'I see you''re putting your travel to good use. Congrats!', '2013-03-14 17:26:49.000000', NULL, 0),
